import { useRef, useEffect, useState } from 'react';
import { useChatContext } from '@/components/ChatContext';
import { AgentId } from '@/types/Agent';
import { Message } from '@/types/Message';

interface DemoSectionProps {
  activeAgentId: AgentId | null;
}

export function DemoSection({ activeAgentId }: DemoSectionProps) {
  const { messages, isLoading, sendMessage, setMessages } = useChatContext();
  const [inputText, setInputText] = useState('');
  const chatContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages, activeAgentId]);

  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setInputText(e.target.value);
  };

  const handleSend = () => {
    if (inputText.trim() !== '') {
      sendMessage(activeAgentId, inputText);
      setInputText('');
    }
  };

  return (
    <div id="demo" className="w-full max-w-6xl mx-auto flex flex-col items-center h-[800px] bg-white border border-gray-200 rounded-lg shadow-sm dark:bg-gray-800 dark:border-gray-700">
      <div className="flex-1 overflow-y-auto p-6 space-y-6 scrollbar-hide relative z-0" ref={chatContainerRef}>
        {messages.map((msg, idx) => (
          <div key={idx} className={`flex ${msg.isUser ? 'justify-end' : 'justify-start'}`}>
            <div className={`rounded-lg py-2 px-3 ${msg.isUser ? 'bg-blue-600 text-white' : 'bg-gray-200 text-gray-800'}`}>
              {msg.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="rounded-lg py-2 px-3 bg-gray-200 text-gray-800">
              Generating response...
            </div>
          </div>
        )}
      </div>

      <div className="flex items-center p-3 space-x-4 border-t border-gray-200 dark:border-gray-700">
        <textarea
          rows={1}
          value={inputText}
          onChange={handleInputChange}
          placeholder="Type your message..."
          className="w-full text-sm text-gray-900 bg-white border border-gray-300 rounded-lg focus:ring-blue-500 focus:border-blue-500 dark:bg-gray-800 dark:border-gray-700 dark:text-white dark:placeholder-gray-400"
        />
        <button
          onClick={handleSend}
          className="inline-flex justify-center p-2 text-blue-600 rounded-full cursor-pointer hover:bg-blue-100 dark:text-blue-500 dark:hover:bg-gray-700"
